function rotateChain(head: ListNode | null, k: number): ListNode | null {
  const vals: number[] = [];
  for (let p = head; p; p = p.next) vals.push(p.val);
  if (vals.length === 0) return null;
  const s = k % vals.length;
  const rotated = vals.slice(vals.length - s).concat(vals.slice(0, vals.length - s));
  let out: ListNode | null = null;
  for (let i = rotated.length - 1; i >= 0; i--) out = new ListNode(rotated[i], out);
  return out;
}

