class Solution:
    def rotateChain(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:
        vals = []
        p = head
        while p:
            vals.append(p.val)
            p = p.next
        if not vals:
            return None
        s = k % len(vals)
        rotated = vals[len(vals) - s:] + vals[:len(vals) - s]
        out = None
        for v in reversed(rotated):
            out = ListNode(v, out)
        return out

