function rotateChain(head: ListNode | null, k: number): ListNode | null {
  if (!head) return head;
  let tail = head, n = 1;
  while (tail.next) { tail = tail.next; n++; }
  k %= n;
  if (k === 0) return head;
  tail.next = head; // close the ring
  let newTail = tail;
  for (let i = 0; i < n - k; i++) newTail = newTail.next!;
  const newHead = newTail.next;
  newTail.next = null;
  return newHead;
}

